export function parseLockfile(raw) {
    const lock = object.parse(raw);
    if (lock.lockfileVersion !== 2 && lock.lockfileVersion !== 3)
        throw new Error("npm lockfileVersion 2 / 3に対応しています。この形式の依存関係は未照合です。");
