        }
        if (!detail)
            result.status = "partial";
        const fixes = [
            ...new Set((detail?.affected ?? [])
                .filter((a) => a.package.ecosystem === "npm" &&
                a.package.name === dependency.name)
                .flatMap((a) => (a.ranges ?? [])
                .filter((r) => r.type === "SEMVER" || r.type === "ECOSYSTEM")
                .flatMap((r) => r.events.flatMap((e) => e.fixed && version.test(e.fixed) ? [e.fixed] : [])))),
        ];
        result.findings.push({
            ...dependency,
            advisoryId: id,
            summary: detail?.summary?.slice(0, 600) ||
                "概要はアドバイザリで確認してください。",
            url: `https://osv.dev/vulnerability/${encodeURIComponent(id)}`,
            fixes,
            detailStatus: detail ? "available" : "unavailable",
        });
    }
    if (result.findings.some((f) => f.detailStatus === "unavailable"))
        limitations.push("一部のアドバイザリ詳細を取得できませんでした。修正境界は原文で確認してください。");
    return { result, sources, limitations };
}
