            finding.rationale,
            `固定snapshot原文: ${finding.originalText}`,
            finding.uncertainty.reasons.length
                ? `不確実性: ${finding.uncertainty.reasons.join("; ")}`
                : "",
        ]
            .filter(Boolean)
            .join("\n")
            .slice(0, 4000);
