                        message: prior?.coverage.status === "complete"
                            ? `${engine === "static" ? "静的解析" : "依存関係照合"}の保存済み結果を再利用しています`
                            : engine === "static"
                                ? "コードを解析しています"
                                : "依存関係を照合しています",
                        updatedAt: clock(),
                    },
                    updatedAt: clock(),
                });
                if (prior?.coverage.status === "complete") {
                    stages.push(prior);
                    continue;
                }
                this.assertPinnedInputs(run, product, controller.signal);
                const result = diagnosticAnalysisSchema.parse(await analyzeSnapshot(snapshot, {
                    allowDependencyNetwork: run.allowDependencyNetwork,
                    engines: [engine],
                    fetcher: this.options.fetcher,
                    signal: controller.signal,
                }));
                const coverage = result.coverage.find((item) => item.engine === engine);
                if (!coverage)
                    throw new Error("diagnostic engine coverage missing");
                const stage = {
                    findings: result.findings.filter((finding) => finding.engine === engine),
                    coverage,
