                            run = this.save(current, {
                                modelReview: {
                                    enabled: true,
                                    providerId: modelProvider.id,
                                    providerKind: modelProvider.kind === "local" ||
                                        modelProvider.kind === "cloud"
                                        ? modelProvider.kind
                                        : null,
                                    model: modelProvider.model,
                                    configVersion: modelProvider.configVersion,
                                    inputHash: null,
                                    contextHash: null,
                                    budget: modelBudget,
                                    coverage,
                                    record: null,
                                    failure: null,
                                },
