                        modelReview: {
                            ...this.unavailableModelReview(product, modelProvider, message, false, modelBudget),
                            enabled: true,
                            coverage,
                        },
                        updatedAt: clock(),
                    });
                    finalAnalysis = diagnosticAnalysisSchema.parse({
                        findings: analysis.findings,
                        coverage: [
                            ...analysis.coverage,
                            this.modelReviewCoverageToDiagnostic(run.modelReview.coverage),
