            throw new Error("finding review context requires a fixed commit");
        const knowledge = run.knowledge.map((ref) => {
            const item = state.knowledge.find((candidate) => candidate.id === ref.id && candidate.revision === ref.revision);
            if (!item || item.status !== "active")
                throw new Error("diagnostic knowledge context changed");
            return {
                id: ref.id,
                revision: ref.revision,
                contentHash: ref.contentHash,
                sourceRefs: item.sourceRefs,
            };
        });
        const rules = run.rules.map((ref) => {
            const item = state.rules.find((candidate) => candidate.id === ref.id && candidate.revision === ref.revision);
            if (!item ||
                item.status !== "active" ||
                item.appliesToVersion !== run.commit)
                throw new Error("diagnostic rule context changed");
            return {
                id: ref.id,
                revision: ref.revision,
                contentHash: ref.contentHash,
                appliesToVersion: item.appliesToVersion,
                sourceRefs: item.sourceRefs,
            };
        });
        const baseContext = {
            targetVersion: run.commit,
            purpose: state.scope.purpose,
            specificationRevision: run.specificationRevision,
            specificationHash: digest(product.specification),
            metadata: {
                diagnosticMethodologyHash: this.findingReviewMethodologyHash(run, product),
            },
            knowledge,
            rules,
        };
        const currentDocuments = new Map(state.documents.map((document) => [document.id, document]));
        const sourceRefsAllowedForLocal = (refs) => refs.every((source) => {
            const document = currentDocuments.get(source.docId);
            return Boolean(document &&
                (document.classification === "public" ||
                    document.classification === "local"));
        });
        const sourceRefsStillCurrent = (refs) => refs.every((source) => {
            const document = currentDocuments.get(source.docId);
            return Boolean(document &&
                document.revision === source.revision &&
                document.body.includes(source.excerpt));
        });
        const sourceRefsAvailableForScope = (refs) => refs.every((source) => {
            const document = currentDocuments.get(source.docId);
            if (!document)
                return false;
            if (document.revision === source.revision)
                return document.body.includes(source.excerpt);
            return Boolean(document.history.find((version) => version.revision === source.revision &&
                version.body.includes(source.excerpt)));
        });
        const pinnedRules = new Map(run.rules.map((item) => [item.id, item]));
        const rulesCurrent = (refs) => refs.every((ref) => {
            const pinned = pinnedRules.get(ref.id);
            const current = state.rules.find((rule) => rule.id === ref.id && rule.revision === ref.revision);
            return Boolean(pinned &&
                pinned.revision === ref.revision &&
                pinned.contentHash ===
                    (current ? contentHash(current.content) : "") &&
                current?.status === "active" &&
                current.appliesToVersion === run.commit);
        });
        const candidates = state.findings
            .flatMap((finding) => {
            if (finding.judgment === "unconfirmed")
                return [];
            const decision = finding.decisions.at(-1);
            const observation = finding.observationHistory.at(-1);
            const sourceScopeDecision = Boolean(decision &&
                finding.suppressions.some((suppression) => suppression.active &&
                    (suppression.matchPolicy ?? "exact_evidence") ===
                        "source_scope" &&
                    suppression.decisionRevision === decision.revision &&
                    sameModelSourceBinding(suppression.modelSourceBinding, decision.modelSourceBinding)));
            // A decision without observation provenance is legacy/manual data.
            // Keep it in workflow history, but do not let it become model context.
            if (!decision?.contextHash ||
                !decision.evidenceHash ||
                (sourceScopeDecision
                    ? !observation?.evidenceHash
                    : decision.evidenceHash !== observation?.evidenceHash) ||
                decision.contextHash !== observation?.contextHash ||
                decision.targetVersion !== run.commit ||
                !decision.sourceRefs.length ||
                !sourceRefsAllowedForLocal(decision.sourceRefs) ||
                !(sourceScopeDecision
                    ? sourceRefsAvailableForScope(decision.sourceRefs)
                    : sourceRefsStillCurrent(decision.sourceRefs)) ||
                !rulesCurrent(decision.ruleRefs))
                return [];
            if (Boolean(decision.modelSourceBinding) !==
                Boolean(observation?.modelSourceBinding) ||
                (decision.modelSourceBinding &&
                    !sameModelSourceBinding(decision.modelSourceBinding, observation?.modelSourceBinding)))
                return [];
            return [{ findingId: finding.id, decision }];
        })
            .sort((left, right) => Date.parse(left.decision.at) - Date.parse(right.decision.at) ||
            left.findingId.localeCompare(right.findingId));
